/**
 * Celebrations on this device: whether they show, the baseline, and the
 * keys spent here (meta `celebrate`); and the account's keys on the server,
 * which make each moment once across every device (`/me/celebrations`).
 * The rules are pure, in `moments.ts`; this file only reads and writes.
 *
 * Every write is a read-modify-write inside one transaction, so two tabs
 * (or two screens) cannot lose each other's keys. None of them may be called
 * from inside a live query: the write would retrigger the query that made it.
 */
import { effectiveStreak } from '@lexpad/core';
import { isApiError } from '@/api/errors.js';
import { db, getMeta, setMeta, type StoredCelebrate } from '@/db/schema.js';
import { platform } from '@/lib/platform/index.js';
import {
  MASTERED_MILESTONES,
  QUIET_HOURS,
  WORD_MILESTONES,
  afterClaim,
  crossed,
  isBig,
  keys,
  reached,
  runStart,
  streakValuesUpTo,
  type Pick,
} from './moments.js';
import { localDay, loadCelebrate, update } from './view.js';

export {
  CELEBRATE_FEATURE,
  CELEBRATE_OFF,
  celebrationsOn,
  loadCelebrate,
  localDay,
  noteChip,
  type CelebrateView,
} from './view.js';

/**
 * How long a moment waits for the server to say this device won it before
 * the screen shows it anyway (and claims it later, as if offline). Only a
 * screen that has a moment waits at all; a client-side choice about how
 * long a summary may stay blank, not a server value.
 */
export const CLAIM_WAIT_MS = 900;

/** How stale this device's copy of the account's keys may get before the sync reads it again. */
export const KEYS_REFRESH_MS = 6 * 3_600_000;

/** Most keys one claim carries: the API contract's `maxItems`. */
export const CLAIM_CHUNK = 50;

/** Words flagged by the leech prompt that this device remembers. */
export const FLAGGED_KEPT = 200;

/** Most keys kept here; the oldest go first (they are for days long past). */
export const SPENT_KEPT = 1500;

/**
 * The API, loaded when a moment is claimed or the sync runs: Today draws
 * from the entry bundle, and the client is kept out of it.
 */
async function api(): Promise<{
  claim: (keys: readonly string[]) => Promise<string[]>;
  list: () => Promise<string[]>;
}> {
  const [{ me }, { newIdempotencyKey }] = await Promise.all([
    import('@/api/endpoints.js'),
    import('@/api/client.js'),
  ]);
  return {
    claim: (keys) => me.claimCelebrations(keys, newIdempotencyKey()),
    list: () => me.celebrations(),
  };
}

/** Whether the account is in its first `QUIET_HOURS`, by its creation; unknown is not young. */
export function isYoung(createdAt: string | undefined, now: Date = new Date()): boolean {
  if (createdAt === undefined) return false;
  const at = Date.parse(createdAt);
  return !Number.isNaN(at) && now.getTime() - at < QUIET_HOURS * 3_600_000;
}

/** Words in the account that count: not retired. */
export async function countAccountWords(): Promise<number> {
  const [all, retired] = await Promise.all([
    db.words.count(),
    db.progress.filter((progress) => progress.retired).count(),
  ]);
  return Math.max(0, all - retired);
}

/** Words in box 5 across the account, not retired. */
export async function countMastered(): Promise<number> {
  return db.progress
    .where('box')
    .equals(5)
    .filter((progress) => !progress.retired)
    .count();
}

/** What the session being summarised changed, to take back out of a baseline taken after it. */
export interface Exclude {
  reviewed: number;
  mastered: number;
  /** The streak before the session, and after it (today counted). */
  streakBefore: number;
  streakAfter: number;
}

/**
 * Settles, once per device, what counts as already celebrated: the first
 * session if there was practice before, the first recall after two days of
 * practice, the first mastered word, every words and mastered milestone at
 * or below today's counts, every streak value of the run that is going, and
 * every frozen day. Only what is crossed after this is celebrated, so
 * nobody meets six old milestones at once. Taken on the first screen that
 * celebrates; a summary taking it passes what its own session did.
 */
export async function settleCelebrate(now: Date = new Date(), exclude?: Exclude): Promise<void> {
  const today = localDay(now);
  await db.transaction('rw', [db.meta, db.dayStats, db.progress, db.words], async () => {
    if ((await getMeta('celebrate')) !== null) return;
    // Not before the account's own data has arrived once: a baseline taken
    // from an empty database would let every old milestone through.
    if ((await getMeta('lastSyncAt')) === null) return;
    const [stats, words, mastered, streak, user] = await Promise.all([
      db.dayStats.toArray(),
      countAccountWords(),
      countMastered(),
      getMeta('streak'),
      getMeta('user'),
    ]);
    const before = stats.filter((stat) => stat.day < today && stat.reviewed > 0);
    const todayEarlier = (stats.find((stat) => stat.day === today)?.reviewed ?? 0) - (exclude?.reviewed ?? 0);
    const practised = before.length > 0 || todayEarlier > 0;
    const masteredBefore = mastered - (exclude?.mastered ?? 0);
    const streakNow = exclude?.streakBefore ?? effectiveStreak(streak, today);
    // The run's first day: from the session's streak with today in it, or
    // from the last active day (today, or yesterday when today is still open).
    const run =
      exclude !== undefined
        ? runStart(today, exclude.streakAfter)
        : (streak.lastActiveDay ?? today) - Math.max(1, streakNow) + 1;
    const spent = [
      ...(practised ? [keys.firstSession] : []),
      ...(before.length >= 2 ? [keys.firstRecall] : []),
      ...(masteredBefore > 0 ? [keys.firstMastered] : []),
      ...reached(WORD_MILESTONES, words).map((value) => keys.words(value)),
      ...reached(MASTERED_MILESTONES, masteredBefore).map((value) => keys.mastered(value)),
      ...(streakNow > 0 ? streakValuesUpTo(streakNow).map((value) => keys.streak(run, value)) : []),
      ...(streak.frozenDays ?? []).map((day) => keys.freeze(day)),
    ];
    const fresh: StoredCelebrate = {
      settledDay: today,
      settledAt: now.toISOString(),
      youngAtSettle: isYoung(user?.createdAt, now) || !practised,
      spent,
      pending: [],
      flagged: [],
      pendingWords: null,
      busy: {
        asOf: today,
        best: before.reduce((best, stat) => Math.max(best, stat.reviewed), 0),
        days: before.length,
      },
      chip: streakNow,
      off: false,
      fetchedAt: null,
    };
    await setMeta('celebrate', fresh);
  });
}

/** Keys that only matter for a few days are dropped once those days are past; the rest are capped. */
export function prune(spent: readonly string[], today: number): string[] {
  const dayBound = /^(alldone|busiest|big):(\d+)$/;
  const kept = spent.filter((key) => {
    const match = dayBound.exec(key);
    return match === null || Number(match[2]) >= today - 1;
  });
  return kept.length > SPENT_KEPT ? kept.slice(kept.length - SPENT_KEPT) : kept;
}

/**
 * Spends keys here. Answers which of `wanted` were still open, so a screen
 * whose moment another tab just took shows nothing. `pending` marks them for
 * the server (shown offline, or the claim did not answer in time).
 */
async function spendHere(wanted: readonly string[], pending: boolean, today: number): Promise<Set<string>> {
  const open = new Set<string>();
  await update((state) => {
    const had = new Set(state.spent);
    for (const key of wanted) if (!had.has(key)) open.add(key);
    if (open.size === 0) return undefined;
    return {
      ...state,
      spent: prune([...state.spent, ...open], today),
      pending: pending ? [...new Set([...state.pending, ...open])] : state.pending,
    };
  });
  return open;
}

/** Keys the server now knows about, one way or the other, are no longer pending. */
async function told(sent: readonly string[]): Promise<void> {
  const done = new Set(sent);
  await update((state) => ({ ...state, pending: state.pending.filter((key) => !done.has(key)) }));
}

/** A claim that answers within `ms`, or undefined when it did not (it still lands later). */
function within<T>(promise: Promise<T>, ms: number): Promise<T | undefined> {
  return new Promise((resolve) => {
    const timer = window.setTimeout(() => {
      resolve(undefined);
    }, ms);
    promise.then(
      (value) => {
        window.clearTimeout(timer);
        resolve(value);
      },
      () => {
        window.clearTimeout(timer);
        resolve(undefined);
      },
    );
  });
}

/**
 * Makes a pick this device's to show. Its keys are spent here first (a tab
 * that already spent the main one shows nothing). With something to show
 * and a connection, the server is asked first and only what this device won
 * is shown: a main moment another device won is dropped, and a big one
 * whose day another device already had becomes a line. Offline, or with no
 * answer in `CLAIM_WAIT_MS`, the moment shows and its keys wait for the
 * next sync, after which no other device shows it. A pick with nothing to
 * show (celebrations off, the first hours) is spent here only.
 */
export async function claimPick(pick: Pick, today: number, waitMs: number = CLAIM_WAIT_MS): Promise<Pick> {
  if (pick.spent.length === 0) return pick;
  const toServer = pick.main !== undefined;
  const online = platform.network.online;
  const open = await spendHere(pick.spent, toServer && !online, today);
  const main = pick.main;
  if (main === undefined) return pick;
  if (!open.has(main.key)) return { spent: pick.spent };
  const local: Pick = {
    main:
      isBig(main) && !open.has(keys.big(today))
        ? { ...main, size: main.id === 'words' ? 'toast' : 'line' }
        : main,
    ...(pick.extra !== undefined && open.has(pick.extra.key) ? { extra: pick.extra } : {}),
    spent: pick.spent,
  };
  if (!online) return local;

  const sent = [...open].slice(0, CLAIM_CHUNK);
  const settled = api()
    .then((server) => server.claim(sent))
    .then(
      (won) => ({ answered: true as const, won }),
      (error: unknown) => ({ answered: false as const, missing: isApiError(error, 'notFound') }),
    );
  const outcome = await within(settled, waitMs);
  if (outcome?.answered === true) return afterClaim(local, new Set(outcome.won), today);
  // No answer in time, or a failure: shown, as offline would be, and the
  // keys wait for the next sync (a server without the endpoint has nothing
  // to be told). A late answer still takes them off the list.
  if (!outcome?.missing) {
    await update((state) => ({ ...state, pending: [...new Set([...state.pending, ...sent])] }));
  }
  void settled.then(async (late) => {
    if (late.answered) await told(sent);
  });
  return local;
}

/**
 * After a sync: tells the server about keys spent offline, and reads the
 * account's keys again when the copy is stale, so a moment another device
 * had is not offered here. Never throws; never on the way to a first paint.
 */
export async function syncCelebrations(now: Date = new Date()): Promise<void> {
  const view = await loadCelebrate();
  if (!view.on || view.state === null || !platform.network.online) return;
  try {
    const pending = view.state.pending;
    for (let start = 0; start < pending.length; start += CLAIM_CHUNK) {
      const chunk = pending.slice(start, start + CLAIM_CHUNK);
      await (await api()).claim(chunk);
      await told(chunk);
    }
    const fetched = view.state.fetchedAt;
    if (fetched === null || now.getTime() - fetched >= KEYS_REFRESH_MS) {
      const theirs = await (await api()).list();
      await update((state) => ({
        ...state,
        spent: prune([...new Set([...state.spent, ...theirs])], localDay(now)),
        fetchedAt: now.getTime(),
      }));
    }
  } catch (error) {
    // A server without the endpoint: stop asking, keep what is here.
    if (isApiError(error, 'notFound')) {
      await update((state) => ({ ...state, pending: [], fetchedAt: now.getTime() }));
    }
  }
}

/** Settings → Practice → Celebrations. */
export async function setCelebrationsOff(off: boolean): Promise<void> {
  await update((state) => (state.off === off ? undefined : { ...state, off }));
}

/** The leech prompt flagged these words on this device. */
export async function noteFlagged(wordIds: readonly string[]): Promise<void> {
  if (wordIds.length === 0) return;
  await update((state) => {
    const missing = wordIds.filter((id) => !state.flagged.includes(id));
    if (missing.length === 0) return undefined;
    return { ...state, flagged: [...state.flagged, ...missing].slice(-FLAGGED_KEPT) };
  });
}

/**
 * A save took the account from `before` words to `after`: the highest
 * milestone crossed waits for the notebook's toast or Today, today only.
 * Synced words are never a crossing, because only a save here calls this.
 */
export async function noteWordsSaved(before: number, after: number, now: Date = new Date()): Promise<void> {
  const value = crossed(WORD_MILESTONES, before, after);
  if (value === undefined) return;
  const today = localDay(now);
  await update((state) =>
    state.spent.includes(keys.words(value)) ? undefined : { ...state, pendingWords: { value, day: today } },
  );
}

/** The last save's milestone being noted; the notebook's toast waits for it. */
let noting: Promise<void> = Promise.resolve();

/** Resolves once the words milestone of the last save has been noted. */
export function wordsNoted(): Promise<void> {
  return noting;
}

/**
 * Runs a save and notes the words milestone it crossed, if any. The save
 * waits only for one indexed count before it; the rest (retired words are
 * not counted, and a save never retires one) is done after it, and the
 * notebook's toast waits for that (`wordsNoted`). Never fails because of
 * the count: a count that fails notes nothing.
 */
export async function trackWords<T>(save: () => Promise<T>): Promise<T> {
  // A device that has not taken its baseline yet takes it now, before the
  // save, so the word being added is not counted as already celebrated.
  await settleCelebrate().catch(() => undefined);
  const before = await db.words.count().catch(() => undefined);
  const result = await save();
  if (before !== undefined) {
    noting = (async () => {
      const [after, retired] = await Promise.all([
        db.words.count(),
        db.progress.filter((progress) => progress.retired).count(),
      ]);
      await noteWordsSaved(before - retired, after - retired);
    })().catch(() => undefined);
  }
  return result;
}

/** The words milestone waiting for today, if any; one from an earlier day is dropped. */
export function wordsWaiting(state: StoredCelebrate | null, today: number): number | undefined {
  const waiting = state?.pendingWords;
  return waiting?.day === today ? waiting.value : undefined;
}

/** The words milestone was shown (or passed over): it waits no more. */
export async function clearPendingWords(): Promise<void> {
  await update((state) => (state.pendingWords === null ? undefined : { ...state, pendingWords: null }));
}

/**
 * The busiest day before today and how many days had practice, brought up
 * to date from the days since it was last kept: never a scan of the whole
 * history.
 */
export async function busyBefore(today: number): Promise<{ best: number; days: number }> {
  const state = await getMeta('celebrate');
  const busy = state?.busy ?? { asOf: today, best: 0, days: 0 };
  if (busy.asOf >= today) return { best: busy.best, days: busy.days };
  const since = await db.dayStats.where('day').between(busy.asOf, today, true, false).toArray();
  const next = {
    asOf: today,
    best: since.reduce((best, stat) => Math.max(best, stat.reviewed), busy.best),
    days: busy.days + since.filter((stat) => stat.reviewed > 0).length,
  };
  await update((current) => ({ ...current, busy: next }));
  return { best: next.best, days: next.days };
}

/** Due words left today across the account: started, not retired, due by today. */
export async function countDueLeft(today: number): Promise<number> {
  return db.progress
    .where('dueDay')
    .belowOrEqual(today)
    .filter((progress) => !progress.retired && progress.reps > 0)
    .count();
}

/** Says a moment by touch on the phone apps: light for a line, success for a big one. Never fails. */
export function feel(size: 'line' | 'toast' | 'burst' | 'takeover'): void {
  try {
    if (size === 'burst' || size === 'takeover') platform.haptics.success();
    else platform.haptics.correct();
  } catch {
    /* a device without a motor, or a shell without the plugin, is not an error */
  }
}

/**
 * One of the app's own big moments was shown (Pro arrived, Get started
 * finished): it takes the day's big slot, so no burst or takeover follows
 * it the same day. Told to the server with the next sync, never on the way.
 */
export async function noteBigMoment(now: Date = new Date()): Promise<void> {
  const today = localDay(now);
  await spendHere([keys.big(today)], true, today);
}
